@extends('layouts.app') @section('content')<section class="section"><div class="wrap"><div class="eyebrow">Your selection</div><h2>Shopping bag</h2>@if(!$cart)<p>Your bag is empty. <a style="color:var(--green)" href="{{ route('shop') }}">Continue shopping.</a></p>@else<form method="post" action="{{ route('cart.update') }}">@csrf @method('PATCH')<table class="table"><tr><th>Product</th><th>Qty</th><th>Price</th><th></th></tr>@php $total=0 @endphp @foreach($cart as $row) @php $line=$row['price'] ? $row['price']*$row['quantity'] : 0; $total+=$line @endphp<tr><td>{{ $row['name'] }}</td><td><input style="width:70px;padding:8px" type="number" name="quantity[{{ $row['id'] }}]" value="{{ $row['quantity'] }}" min="0"></td><td>{{ $row['price_on_request']?'On request':'₦'.number_format($line,2) }}</td><td><button class="btn alt" form="remove-{{ $row['id'] }}">Remove</button></td></tr></table><button class="btn alt" style="margin-top:15px">Update bag</button></form>@foreach($cart as $row)<form id="remove-{{ $row['id'] }}" method="post" action="{{ route('cart.remove',$row['id']) }}">@csrf @method('DELETE')</form>@endforeach<div style="margin-top:30px;font-size:20px">Total: <strong>₦{{ number_format($total,2) }}</strong></div><a class="btn" style="margin-top:15px" href="{{ route('checkout') }}">Proceed to checkout</a>@endif</div></section>@endsection
